1	import { Language, SymbolKind, RelationshipKind } from "@yats/shared";
2	import type { Symbol, Relationship, AnalysisResult } from "@yats/shared";
3	import { AbstractAnalyzer } from "@yats/analyzer-interface";
4	import { hashContent, createSymbolId } from "@yats/shared";
5	import { spawn } from "node:child_process";
6	import * as path from "node:path";
7	
8	// ============================================================
9	// Go Analyzer — spawns Go bridge process
10	// ============================================================
11	
12	const GO_EXTENSIONS = new Set([".go"]);
13	
14	interface GoBridgeResult {
15	  symbols: RawGoSymbol[];
16	  relationships: RawGoRelationship[];
17	  errors: string[];
18	  warnings: string[];
19	}
20	
21	interface RawGoSymbol {
22	  id: string;
23	  name: string;
24	  kind: string;
25	  language: string;
26	  location: {
27	    repository: string;
28	    relativePath: string;
29	    startLine: number;
30	    endLine: number;
31	    startColumn: number;
32	    endColumn: number;
33	  };
34	  namespace: string;
35	  parentClass: string | null;
36	  signature: string | null;
37	  docComment: string | null;
38	  sourceSnippet: string;
39	  contentHash: string;
40	  metadata: Record<string, unknown>;
41	}
42	
43	interface RawGoRelationship {
44	  id: string;
45	  sourceSymbolId: string;
46	  targetSymbolId: string;
47	  kind: string;
48	  metadata: Record<string, unknown>;
49	}
50	
51	export class GoAnalyzer extends AbstractAnalyzer {
52	  readonly language = Language.GO;
53	  private readonly bridgePath: string;
54	
55	  constructor(bridgePath?: string) {
56	    super();
57	    this.bridgePath = bridgePath ?? path.join(
58	      import.meta.dirname,
59	      "go-bridge",
60	      "analyze.go",
61	    );
62	  }
63	
64	  canAnalyze(filePath: string, _content: string): boolean {
65	    return GO_EXTENSIONS.has(path.extname(filePath).toLowerCase());
66	  }
67	
68	  async analyze(
69	    filePath: string,
70	    content: string,
71	    repositoryName: string,
72	  ): Promise<AnalysisResult> {
73	    try {
74	      return await this.analyzeWithBridge(filePath, repositoryName);
75	    } catch {
76	      return this.analyzeFallback(filePath, content, repositoryName);
77	    }
78	  }
79	
80	  private async analyzeWithBridge(
81	    filePath: string,
82	    repositoryName: string,
83	  ): Promise<AnalysisResult> {
84	    // In Docker: use pre-compiled binary. In dev: use "go run".
85	    const bridgeBin = process.env.YATS_GO_BRIDGE;
86	    const fs = await import("node:fs");
87	
88	    const useBinary = bridgeBin && fs.existsSync(bridgeBin) && fs.statSync(bridgeBin).size > 0;
89	    const cmd = useBinary ? bridgeBin : "go";
90	    const args = useBinary
91	      ? ["--file", filePath, "--repo", repositoryName]
92	      : ["run", this.bridgePath, "--file", filePath, "--repo", repositoryName];
93	
94	    return new Promise((resolve, reject) => {
95	      const proc = spawn(cmd, args, {
96	        timeout: 30000,
97	        stdio: ["pipe", "pipe", "pipe"],
98	      });
99	
100	      let stdout = "";
101	      let stderr = "";
102	
103	      proc.stdout.on("data", (d: Buffer) => (stdout += d.toString()));
104	      proc.stderr.on("data", (d: Buffer) => (stderr += d.toString()));
105	
106	      proc.on("close", (code: number) => {
107	        if (code !== 0) {
108	          reject(new Error(`Go bridge exited with code ${code}: ${stderr}`));
109	          return;
110	        }
111	        try {
112	          const result = JSON.parse(stdout) as GoBridgeResult;
113	          resolve({
114	            symbols: this.normalizeSymbols(result.symbols),
115	            relationships: this.normalizeRelationships(result.relationships),
116	            errors: (result.errors ?? []).map((e: string) => ({
117	              message: e, line: 0, column: 0, severity: "error" as const,
118	            })),
119	            warnings: (result.warnings ?? []) as any[],
120	          });
121	        } catch (err: any) {
122	          reject(new Error(`Failed to parse Go bridge output: ${err.message}`));
123	        }
124	      });
125	
126	      proc.on("error", reject);
127	    });
128	  }
129	
130	  private analyzeFallback(
131	    filePath: string,
132	    content: string,
133	    repositoryName: string,
134	  ): AnalysisResult {
